/**
 * End-to-end test of clinic self-registration against STAGING, over real HTTP:
 *
 *   signup → (pending, cannot sign in) → admin edits + approves → clinic manager signs in
 *   → manager adds a location (QR auto-generated by mcm-bridge) and a staff member
 *   → staff signs in → manager forms CRUD → tenant isolation and role checks
 *   → admin QR route → reject path → cleanup
 *
 * Needs: MEMR dev server (default http://localhost:3000) and mcm-bridge running with
 * BRIDGE_URL pointing at it, migrations 133 and 134 applied to the EMR staging DB.
 *
 * Run:  node scripts/e2e-clinic-signup.mjs          (cleans up everything it created)
 *       node scripts/e2e-clinic-signup.mjs --keep   (leaves the test data for inspection)
 *
 * Refuses to run unless both Supabase URLs are the staging projects.
 */

import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { createClient } from '@supabase/supabase-js'

const here = path.dirname(fileURLToPath(import.meta.url))
const EMR_STAGING = 'bssjlpqdgmtgaxvadwdh'
const PORTAL_STAGING = 'reiogvwjunkdrbhwewvv'
const KEEP = process.argv.includes('--keep')
const BASE = process.env.E2E_BASE_URL || 'http://localhost:3000'

function loadEnv(file) {
  const out = {}
  if (!fs.existsSync(file)) return out
  for (const line of fs.readFileSync(file, 'utf8').split('\n')) {
    const t = line.trim()
    if (!t || t.startsWith('#')) continue
    const i = t.indexOf('=')
    if (i > 0) out[t.slice(0, i).trim()] = t.slice(i + 1).trim()
  }
  return out
}

const memrEnv = loadEnv(path.join(here, '..', '.env'))
const bridgeEnv = loadEnv(path.join(here, '..', '..', 'mcm-bridge', '.env'))
const EMR_URL = memrEnv.NEXT_PUBLIC_SUPABASE_URL
const PORTAL_URL = bridgeEnv.SUPABASE_PORTAL_URL

if (!EMR_URL?.includes(EMR_STAGING) || !PORTAL_URL?.includes(PORTAL_STAGING)) {
  console.error('Refusing to run: MEMR and mcm-bridge must both point at the staging Supabase projects.')
  process.exit(2)
}

const emr = createClient(EMR_URL, memrEnv.SUPABASE_SECRET_KEY, { auth: { persistSession: false } })
const portal = createClient(PORTAL_URL, bridgeEnv.SUPABASE_PORTAL_SECRET_KEY, { auth: { persistSession: false } })

// ---------- tiny harness ----------
let passed = 0
let failed = 0
const created = { users: [], emrLocations: [], tenantIds: [], signupIds: [], formIds: [] }

function check(name, cond, detail) {
  if (cond) {
    passed++
    console.log(`  ✓ ${name}`)
  } else {
    failed++
    console.log(`  ✗ ${name}${detail !== undefined ? `\n      ${typeof detail === 'string' ? detail : JSON.stringify(detail).slice(0, 400)}` : ''}`)
  }
  return cond
}

function step(title) {
  console.log(`\n▸ ${title}`)
}

class Session {
  constructor() {
    this.cookies = new Map()
  }
  absorb(res) {
    for (const c of res.headers.getSetCookie?.() ?? []) {
      const [pair] = c.split(';')
      const i = pair.indexOf('=')
      this.cookies.set(pair.slice(0, i), pair.slice(i + 1))
    }
  }
  header() {
    return [...this.cookies].map(([k, v]) => `${k}=${v}`).join('; ')
  }
  async req(method, url, body) {
    const res = await fetch(BASE + url, {
      method,
      redirect: 'manual',
      headers: {
        ...(body !== undefined ? { 'content-type': 'application/json' } : {}),
        ...(this.cookies.size ? { cookie: this.header() } : {}),
      },
      body: body !== undefined ? JSON.stringify(body) : undefined,
    })
    this.absorb(res)
    const text = await res.text()
    let json = null
    try {
      json = text ? JSON.parse(text) : null
    } catch {
      json = null
    }
    return { status: res.status, json, location: res.headers.get('location') }
  }
}

async function login(email, password) {
  const s = new Session()
  const r = await s.req('POST', '/api/auth/login', { email, password })
  return { session: s, ...r }
}

const stamp = Date.now()
const PASSWORD = `E2e!Pass${stamp % 100000}`
const mail = (who) => `e2e-${who}-${stamp}@e2e.myclinicmd.test`

async function portalIdFor(emrLocationId) {
  const { data } = await emr.from('locations').select('external_location_id').eq('id', emrLocationId).maybeSingle()
  return data?.external_location_id ?? null
}

async function qrRowFor(portalId) {
  if (portalId == null) return null
  const { data } = await portal.from('Qr').select('id, locationid, qrcode').eq('locationid', portalId).maybeSingle()
  return data
}

// ---------- the flow ----------
async function run() {
  console.log(`E2E clinic signup — ${BASE} — EMR ${EMR_STAGING} / portal ${PORTAL_STAGING}`)

  step('Preflight')
  const { error: tblErr } = await emr.from('signup_requests').select('id').limit(1)
  if (!check('migration 133 applied (signup_requests exists)', !tblErr, tblErr?.message)) return
  const { error: colErr } = await emr.from('profiles').select('tenant_id').limit(1)
  if (!check('migration 134 applied (profiles.tenant_id exists)', !colErr, colErr?.message)) return

  const signup = {
    contact_name: 'E2E Manager',
    email: mail('manager'),
    password: PASSWORD,
    tenant_name: `E2E Clinic ${stamp}`,
    location_name: `E2E Main ${stamp}`,
    location_address: '123 Test Street, Houston, TX 77002',
    location_phone: '(555) 010-0000',
    location_email: mail('front'),
  }

  step('Public signup')
  const anon = new Session()
  let r = await anon.req('POST', '/api/auth/clinic-signup', signup)
  check('signup accepted as pending', r.status === 200 && r.json?.status === 'pending', r)
  r = await anon.req('POST', '/api/auth/clinic-signup', signup)
  check('duplicate signup rejected (409)', r.status === 409, r)
  r = await anon.req('POST', '/api/auth/clinic-signup', { ...signup, email: mail('weak'), password: 'weak' })
  check('weak password rejected (400)', r.status === 400, r)

  const { data: reqRow } = await emr.from('signup_requests').select('id, user_id, status').eq('email', signup.email).maybeSingle()
  if (!check('signup_requests row exists', !!reqRow?.id, reqRow)) return
  created.signupIds.push(reqRow.id)
  created.users.push(reqRow.user_id)
  const { data: pendingProfile } = await emr.from('profiles').select('role').eq('uid', reqRow.user_id).maybeSingle()
  check('pending user has no profile/role', !pendingProfile, pendingProfile)
  r = await login(signup.email, PASSWORD)
  check('pending user cannot sign in', r.status !== 200, { status: r.status })

  step('Admin reviews and approves')
  const adminEmail = mail('admin')
  const { data: adminAuth, error: adminErr } = await emr.auth.admin.createUser({
    email: adminEmail,
    password: PASSWORD,
    email_confirm: true,
    user_metadata: { full_name: 'E2E Admin', role: 'admin' },
  })
  if (!check('temporary admin created', !adminErr && adminAuth?.user, adminErr?.message)) return
  created.users.push(adminAuth.user.id)
  // The auth trigger's own profile insert can fail silently (profiles.id must equal the
  // auth user id), so write the profile explicitly, as the app's user-creation code does.
  const adminProfile = { role: 'admin', active: true, full_name: 'E2E Admin', email: adminEmail }
  const { data: existingAdminProfile } = await emr.from('profiles').select('id').eq('uid', adminAuth.user.id).maybeSingle()
  const { error: adminProfileErr } = existingAdminProfile
    ? await emr.from('profiles').update(adminProfile).eq('uid', adminAuth.user.id)
    : await emr.from('profiles').insert({ id: adminAuth.user.id, uid: adminAuth.user.id, ...adminProfile })
  if (!check('temporary admin profile written', !adminProfileErr, adminProfileErr?.message)) return
  const admin = await login(adminEmail, PASSWORD)
  check('admin signs in', admin.status === 200 && admin.json?.role === 'admin', admin.json)

  r = await admin.session.req('GET', '/api/admin/signup-requests?status=pending')
  check('admin sees the pending signup', r.status === 200 && r.json?.data?.some((x) => x.id === reqRow.id), r.status)
  r = await admin.session.req('PATCH', `/api/admin/signup-requests/${reqRow.id}`, { location_phone: '(555) 010-9999' })
  check('admin edits the signup', r.status === 200 && r.json?.data?.location_phone === '(555) 010-9999', r)
  r = await anon.req('GET', '/api/admin/signup-requests')
  check('signups list needs admin (401)', r.status === 401, r.status)

  r = await admin.session.req('POST', `/api/admin/signup-requests/${reqRow.id}/approve`)
  const approved = r.json?.data
  check('admin approves', r.status === 200 && approved?.status === 'approved', r)
  if (!approved?.tenant_id || !approved?.location_id) return
  created.tenantIds.push(approved.tenant_id)
  created.emrLocations.push(approved.location_id)

  const { data: mgrProfile } = await emr.from('profiles').select('role, tenant_id, active').eq('uid', reqRow.user_id).maybeSingle()
  check('manager profile: clinic_manager of the new tenant', mgrProfile?.role === 'clinic_manager' && mgrProfile?.tenant_id === approved.tenant_id, mgrProfile)
  const { data: newLoc } = await emr.from('locations').select('tenant_id, phone').eq('id', approved.location_id).maybeSingle()
  check('first location belongs to the tenant, with the edited phone', newLoc?.tenant_id === approved.tenant_id && /9999/.test(newLoc?.phone ?? ''), newLoc)
  const firstPortalId = await portalIdFor(approved.location_id)
  check('first location synced to the portal', firstPortalId != null)
  check('first location got its QR automatically', !!(await qrRowFor(firstPortalId))?.qrcode)

  step('Clinic manager')
  const mgr = await login(signup.email, PASSWORD)
  check('manager signs in as clinic_manager', mgr.status === 200 && mgr.json?.role === 'clinic_manager', mgr.json)
  const m = mgr.session
  r = await m.req('GET', '/manage')
  check('/manage opens', r.status === 200, r.status)
  for (const p of ['/dashboard', '/admin', '/patient-file/1']) {
    r = await m.req('GET', p)
    check(`${p} redirects to /manage`, r.status >= 300 && r.status < 400 && /\/manage$/.test(r.location ?? ''), r.location)
  }
  r = await m.req('GET', '/api/manage/me')
  check('manager sees own tenant', r.json?.tenant?.id === approved.tenant_id, r.json)
  for (const p of ['/api/admin/users', '/api/admin/locations', '/api/admin/signup-requests']) {
    r = await m.req('GET', p)
    check(`${p} forbidden for manager`, r.status === 403, r.status)
  }
  r = await m.req('GET', `/api/admin/locations/${approved.location_id}/qr`)
  check('manager cannot use the admin QR route', r.status === 403, r.status)

  r = await m.req('POST', '/api/manage/locations', {
    title: `E2E Second ${stamp}`,
    address: '456 Test Ave, Houston, TX 77003',
    phone: '(555) 010-2222',
    email: mail('second'),
    is_active: true,
  })
  const second = r.json?.data
  check('manager adds a location', r.status === 200 && second?.tenant_id === approved.tenant_id, r)
  if (second?.id) created.emrLocations.push(second.id)
  const secondPortalId = second?.id ? await portalIdFor(second.id) : null
  check('new location got its QR automatically', !!(await qrRowFor(secondPortalId))?.qrcode)

  const { data: foreign } = await emr.from('locations').select('id').neq('tenant_id', approved.tenant_id).limit(1).maybeSingle()
  r = await m.req('PATCH', `/api/manage/locations/${foreign.id}`, { title: 'hijack' })
  check("manager cannot edit another tenant's location", r.status === 400, r)

  const staffEmail = mail('nurse')
  r = await m.req('POST', '/api/manage/staff', { name: 'E2E Nurse', email: staffEmail, password: PASSWORD, role: 'nurse', location_ids: [foreign.id] })
  check("staff cannot be assigned to another tenant's location", r.status === 400, r)
  r = await m.req('POST', '/api/manage/staff', { name: 'E2E Nurse', email: staffEmail, password: PASSWORD, role: 'nurse', location_ids: [approved.location_id] })
  check('manager adds a nurse', r.status === 200 && !!r.json?.uid, r)
  const staffUid = r.json?.uid
  if (staffUid) created.users.push(staffUid)

  r = await m.req('GET', '/api/manage/staff')
  check('staff list shows the nurse at the location', r.json?.staff?.some((s) => s.uid === staffUid && s.locations.some((l) => l.id === approved.location_id)), r.json?.staff)
  r = await m.req('PATCH', '/api/manage/staff', { uid: staffUid, role: 'pa' })
  check('manager changes the role to PA', r.status === 200, r)
  r = await m.req('PATCH', '/api/manage/staff', { uid: adminAuth.user.id, active: false })
  check('manager cannot edit users outside the clinic', r.status === 400, r)

  const staff = await login(staffEmail, PASSWORD)
  check('new staff signs in with the clinical role', staff.status === 200 && staff.json?.role === 'pa', staff.json)
  r = await staff.session.req('GET', '/api/manage/staff')
  check('staff cannot use manager APIs', r.status === 403, r.status)

  r = await m.req('POST', '/api/manage/forms', { name: `E2E Consent ${stamp}`, html: '<p>I consent to treatment.</p>', is_active: true })
  const formId = r.json?.data?.id
  check('manager creates a consent form', r.status === 200 && !!formId, r)
  if (formId) created.formIds.push(formId)
  r = await m.req('DELETE', `/api/manage/forms/${formId}`)
  check('active form cannot be deleted', r.status === 400, r)
  r = await m.req('PATCH', `/api/manage/forms/${formId}`, { is_active: false })
  check('manager deactivates the form', r.status === 200 && r.json?.data?.is_active === false, r)
  r = await m.req('DELETE', `/api/manage/forms/${formId}`)
  check('manager deletes the form', r.status === 200, r)
  if (r.status === 200) created.formIds = created.formIds.filter((id) => id !== formId)

  step('Admin QR')
  r = await admin.session.req('GET', `/api/admin/locations/${approved.location_id}/qr`)
  check('admin sees the location QR', r.status === 200 && !!r.json?.data?.qrcode, r)
  r = await admin.session.req('POST', `/api/admin/locations/${approved.location_id}/qr`)
  check('regenerate keeps the same QR', r.status === 200 && r.json?.data?.id === (await qrRowFor(firstPortalId))?.id, r)

  step('Reject path')
  const rejectEmail = mail('rejected')
  r = await anon.req('POST', '/api/auth/clinic-signup', { ...signup, email: rejectEmail, tenant_name: `E2E Rejected ${stamp}` })
  const { data: rej } = await emr.from('signup_requests').select('id, user_id').eq('email', rejectEmail).maybeSingle()
  if (rej?.id) {
    created.signupIds.push(rej.id)
    created.users.push(rej.user_id)
  }
  r = await admin.session.req('POST', `/api/admin/signup-requests/${rej?.id}/reject`, { note: 'E2E test' })
  check('admin rejects', r.status === 200 && r.json?.data?.status === 'rejected', r)
  const { data: gone } = await emr.auth.admin.getUserById(rej?.user_id)
  check('rejected user is deleted', !gone?.user)
}

// ---------- cleanup (staging only, test rows only) ----------
async function cleanup() {
  if (KEEP) {
    console.log('\n--keep: test data left in staging', created)
    return
  }
  step('Cleanup')
  const users = [...new Set(created.users.filter(Boolean))]
  for (const id of created.formIds) await emr.from('forms').delete().eq('id', id)
  if (users.length) {
    await emr.from('user_locations').delete().in('user_uid', users)
    await emr.from('doctors').delete().in('user_id', users)
    await emr.from('nurses').delete().in('user_id', users)
    await emr.from('profiles').delete().in('uid', users)
  }
  for (const id of created.signupIds) await emr.from('signup_requests').delete().eq('id', id)
  for (const id of users) await emr.auth.admin.deleteUser(id).catch(() => {})

  for (const emrId of created.emrLocations) {
    const portalId = await portalIdFor(emrId)
    if (portalId != null) {
      const qr = await qrRowFor(portalId)
      const file = qr?.qrcode?.split('/new_qr/')[1]
      if (file) await portal.storage.from('new_qr').remove([file])
      await portal.from('Qr').delete().eq('locationid', portalId)
      await portal.from('Locations').delete().eq('id', portalId)
    }
    await emr.from('locations').delete().eq('id', emrId)
  }
  for (const tenantId of created.tenantIds) {
    const { data: tenant } = await emr.from('tenants').select('tenant_code').eq('id', tenantId).maybeSingle()
    await emr.from('tenants').delete().eq('id', tenantId)
    if (tenant?.tenant_code) await portal.from('tenants').delete().eq('tenant_code', tenant.tenant_code)
  }
  console.log('  test users, tenant, locations, QR rows/images, forms and signup rows removed')
}

try {
  await run()
} catch (e) {
  failed++
  console.error('\nUnexpected error:', e)
} finally {
  await cleanup().catch((e) => console.error('Cleanup error:', e))
  console.log(`\n${passed} passed, ${failed} failed`)
  process.exit(failed ? 1 : 0)
}
